/* Discussion prototype: in-memory sample data, no production API or storage. */
(() => {
  'use strict';
  const M=window.ThicknessReview,app=document.querySelector('#app'),dialog=document.querySelector('#thickness-dialog');
  let state=M.seed(),view='product',filter='all',moreFilters=false,unwrittenOnly=false,selected=new Set(),menu=false,modal=null,returnFocus=null,toastTimer,groupUndo=null;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=name=>`<i data-lucide="${name}" class="icon" aria-hidden="true"></i>`;
  const btn=(action,label,ic='',cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${label}</button>`;
  const option=(v,label,value)=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label)}</option>`;
  const number=(v,d=2)=>v==null?'—':Number(v).toFixed(d);
  const rows=()=>M.derive(state);
  const filteredRows=()=>rows().filter(r=>!unwrittenOnly||r.detectedThickness.length===0);
  const shownRows=()=>filteredRows().filter(r=>filter==='all'||(filter==='pending'?r.status==='pending':filter==='ready'?r.status!=='pending':filter==='unwritten'?r.detectedThickness.length===0:true));
  const dimensions=[{width:40,length:60},{width:50,length:80},{width:60,length:90},{width:50,length:120},{width:60,length:120}];
  const dimensionKey=d=>d?d.width+'x'+d.length:'';
  function toast(text,undoable=false){const el=document.querySelector('#thickness-toast');el.textContent=text;if(undoable){const undo=document.createElement('button');undo.type='button';undo.dataset.action='undo-group';undo.textContent='撤销';el.append(undo);}el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),undoable?10000:3500);}
  const shortId=id=>{const chars=Array.from(String(id));return chars.length>10?chars.slice(0,6).join('')+'…'+chars.slice(-4).join(''):String(id);};
  function groupValues(group){
    const sameMaterial=group.rows.every(r=>r.materialStatus!=='pending'&&r.materialId===group.rows[0].materialId),materialId=sameMaterial?group.rows[0].materialId:'__mixed';
    const material=state.materials.find(m=>m.id===materialId),targets=group.rows.filter(r=>r.dimensionStatus!=='blank');
    const thicknessEnabled=!!material&&targets.length>0,ruleId=thicknessEnabled&&targets.every(r=>r.ruleId&&r.ruleId===targets[0].ruleId)?targets[0].ruleId:'';
    return {materialId,material,thicknessEnabled,ruleId};
  }
  function groupView(group,index,visible){
    const {materialId,material,thicknessEnabled,ruleId}=groupValues(group),hidden=group.rows.length-visible.length;
    const scope=`${group.platform} / ${group.shopName} · 同链接全部 ${group.rows.length} 个 SKU${hidden?'（含 '+hidden+' 条筛选隐藏行）':''}；选中后统一该字段，尺寸保持原值。`;
    return `<tr class="product-group" data-product-group="${index}"><td><input type="checkbox" name="group-${index}" data-select-group="${index}" aria-label="选择商品 ${esc(group.productId)} 当前显示的 ${visible.length} 条规格" ${visible.every(r=>selected.has(r.id))?'checked':''}></td><td><div class="group-heading"><span class="group-id" tabindex="0" title="${esc(group.productId||'未提供商品 ID')}" aria-label="商品 ID ${esc(group.productId||'未提供')}">ID ${esc(group.productId?shortId(group.productId):'未提供')}</span><span class="group-hint" title="${esc(scope)}">同链接批量处理</span></div><div class="group-meta">共 ${group.rows.length} 个 SKU${hidden?' · 含隐藏 '+hidden+' 条':''}</div></td><td><select name="group-material-${index}" data-group-material="${index}" aria-label="商品 ${esc(group.productId)} 全部 ${group.rows.length} 个 SKU 的材质" title="${esc(scope)}">${materialId==='__mixed'?option('__mixed','请选择',materialId):''}${option('','保留为空',materialId)}${state.materials.map(m=>option(m.id,m.name,materialId)).join('')}</select></td><td><select name="group-thickness-${index}" data-group-thickness="${index}" aria-label="商品 ${esc(group.productId)} 全部 ${group.rows.length} 个 SKU 的厚度" title="${esc(scope)}" ${thicknessEnabled?'':'disabled'}>${option('',thicknessEnabled?'批量选择':materialId==='__mixed'?'先统一材质':'无需计算',ruleId)}${(material?.rules||[]).map(r=>option(r.id,r.thickness+' mm',ruleId)).join('')}</select></td><td colspan="4"></td></tr>`;
  }
  function applyGroup(index,field,value,focusName){
    const group=M.productGroups(state)[index];if(!group)throw Error('商品分组不存在');
    const patch={};if(field==='material'){if(value==='__mixed')return render(focusName);patch.material=value;}else{if(!value)return render(focusName);const current=groupValues(group);if(!current.thicknessEnabled)throw Error('请先统一此商品的材质');patch.thickness={materialId:current.materialId,ruleId:value};}
    const before=structuredClone(state.rows),result=M.applyReview(state,group.rows.map(r=>r.id),patch,true);
    groupUndo={before,after:JSON.stringify(state.rows),focusName};render(focusName);
    toast('同链接 '+result.changed+' 个 SKU 已统一'+(field==='material'?'材质':'厚度')+(result.incompatible?'，留空尺寸的规格已跳过':''),true);
  }
  function nav(){return `<aside class="sidebar ${menu?'menu-open':''}"><a class="brand" href="thickness-review-20260918.html" aria-label="综合复核原型首页"><span class="brand-mark"><img src="assets/app-icon.png" width="34" height="34" alt=""></span><div><div class="brand-title">地垫工作台</div><div class="brand-sub">全域投放 · 盈亏测算</div></div></a><button type="button" class="mobile-nav" data-action="menu" aria-expanded="${menu}">${icon('menu')}导航</button><div class="shop-picker"><label>当前店铺</label><div class="scope-value">${icon('store')}地垫旗舰店</div></div><nav class="nav-group" aria-label="主导航"><a class="nav-item" href="review-20260918.html">${icon('layout-dashboard')}投放测算</a><button type="button" class="nav-item ${view==='library'?'active':''}" data-action="library" ${view==='library'?'aria-current="page"':''}>${icon('library')}可复用规则</button><button type="button" class="nav-item ${view==='product'?'active':''}" data-action="product" ${view==='product'?'aria-current="page"':''}>${icon('table-2')}商品转表</button></nav><div class="sidebar-bottom"><div class="local-status"><span class="status-dot"></span>综合复核 · 交互原型</div><div class="view-label">示例数据 · 刷新可重新体验</div></div></aside>`;}
  function header(title,sub,action){return `<header class="page-header"><div class="page-heading"><h1>${title}</h1><p class="page-sub">${sub}</p></div>${action}</header>`;}
  function product(){
    const all=rows(),pending=all.filter(r=>r.status==='pending').length,filtered=filteredRows(),filteredPending=filtered.filter(r=>r.status==='pending').length,shown=shownRows(),shownIds=new Set(shown.map(r=>r.id));
    const body=M.productGroups(state).map((group,index)=>{const visible=group.rows.filter(r=>shownIds.has(r.id));return visible.length?groupView(group,index,visible)+visible.map(rowView).join(''):'';}).join('');
    return header('商品转表','按商品复核材质、厚度和尺寸，自动计算重量与成本。',btn('preview-export','预览导出结果','download','primary',pending?'disabled':''))+`<section class="wide-content"><div class="file-strip"><div class="file-info">${icon('file-spreadsheet')}<div><strong>商品规格 · 综合复核示例.xlsx</strong><p>3 个商品 · 6 条 SKU · 材质、厚度与尺寸异常示例</p></div></div></div><div class="review-control"><div class="review-filter-bar"><div class="review-filters" aria-label="复核筛选">${[['all','全部规格',filtered.length],['pending','待复核',filteredPending],['ready','已确认',filtered.length-filteredPending]].map(([k,label,count])=>`<button type="button" name="filter-${k}" class="filter-btn" data-action="filter" data-value="${k}" aria-pressed="${filter===k}">${label}<span class="filter-count">${count}</span></button>`).join('')}</div><div class="more-filter-inline"><span id="extra-filters" ${moreFilters?'':'hidden'}>${moreFilters?`<button type="button" class="filter-btn extra-filter-btn" data-action="filter-unwritten" name="filter-unwritten" aria-pressed="${unwrittenOnly}">未写厚度<span class="filter-count">${all.filter(r=>r.detectedThickness.length===0).length}</span></button>`:''}</span>${moreFilters?`<button type="button" class="filter-btn collapse-filter" data-action="more-filters" name="more-filters" aria-expanded="true" aria-controls="extra-filters" aria-label="收起更多筛选" title="收起更多筛选">${icon('chevron-left')}</button>`:btn('more-filters','更多筛选'+icon('chevron-right'),'','ghost more-filters',`name="more-filters" aria-expanded="false" aria-controls="extra-filters"`)}</div></div><div class="review-tools"><span>已选 ${selected.size} 条</span>${btn('batch','批量处理所选','list-checks','',selected.size?'':'disabled')}</div></div><div class="table-scroller" tabindex="0" aria-label="规格复核表，可横向滚动"><table class="thickness-table"><caption class="sr-only">按商品 ID 分组的材质、厚度、尺寸复核</caption><thead><tr><th><input type="checkbox" name="select-all" aria-label="选择当前显示全部规格" ${shown.length&&shown.every(r=>selected.has(r.id))?'checked':''} ${shown.length?'':'disabled'}></th><th class="source-col">原商品 / SKU 规格</th><th class="material-col">材质</th><th class="thickness-col">厚度 / mm</th><th class="dimension-col">尺寸 / cm</th><th class="number-col num">重量 / kg</th><th class="number-col num">成本 / 元</th><th class="status-col">状态</th></tr></thead><tbody>${body||'<tr><td colspan="8" class="table-empty">没有符合筛选条件的规格。</td></tr>'}</tbody></table></div><div class="table-footer"><p>显示 ${shown.length} / ${all.length} 条 · ${pending?`还有 ${pending} 条待复核。`:'全部规格已确认，可以预览导出。'}</p><p>同链接下拉选择统一应用于全部 SKU，尺寸保持原值。</p></div></section>`;
  }
  function rowView(r){const mat=state.materials.find(m=>m.id===r.materialId),blank=r.materialStatus==='blank'||r.dimensionStatus==='blank',current=r.ruleId||'';
    let explanation=r.reason||'';
    if(r.rule)explanation=(r.source==='manual'?'人工确认':'自动识别')+' · '+r.rule.costPerSqm+' 元/㎡';
    const dimensionOptions=[...dimensions];if(r.dimension&&!dimensionOptions.some(x=>dimensionKey(x)===dimensionKey(r.dimension)))dimensionOptions.push(r.dimension);
    return `<tr data-row="${esc(r.id)}"><td><input type="checkbox" name="select-${esc(r.id)}" data-select-row="${esc(r.id)}" aria-label="选择 ${esc(r.sku)}" ${selected.has(r.id)?'checked':''}></td><td><p class="product-name">${esc(r.name)}</p><p class="product-spec">${esc(r.spec)}</p><div class="source-id">${esc(r.sku)}</div></td><td><select name="material-${r.id}" data-material="${r.id}" aria-label="${r.sku} 材质" class="${r.materialStatus==='pending'?'needs-review':''}">${r.materialStatus==='pending'?option('__pending','待确认','__pending'):''}${option('','保留为空',r.materialStatus==='pending'?'__pending':r.materialId)}${state.materials.map(m=>option(m.id,m.name,r.materialStatus==='pending'?'__pending':r.materialId)).join('')}</select><div class="cell-hint ${r.materialStatus==='pending'?'warning':''}">${r.materialStatus==='pending'?(r.name.includes('伪亚麻')?'伪亚麻，需人工确认':'需人工确认'):r.materialStatus==='blank'?'已确认留空':r.materialSource==='manual'?'人工确认':'自动识别'}</div></td><td><select name="rule-${r.id}" data-rule="${r.id}" aria-label="${r.sku} 厚度" class="${r.thicknessStatus==='pending'&&r.materialStatus==='value'?'needs-review':''}" ${r.materialStatus!=='value'||blank?'disabled':''}>${option('',blank?'无需计算':r.materialStatus!=='value'?'先确认材质':'请选择厚度',current)}${(mat?.rules||[]).map(x=>option(x.id,x.thickness+' mm',current)).join('')}</select><div class="cell-hint ${r.thicknessStatus==='pending'?'warning':r.source==='manual'?'manual':''}">${esc(explanation)}</div></td><td><select name="dimension-${r.id}" data-dimension="${r.id}" aria-label="${r.sku} 尺寸" class="${r.dimensionStatus==='pending'?'needs-review':''}">${r.dimensionStatus==='pending'?option('__pending','待确认','__pending'):''}${option('blank','保留为空',r.dimensionStatus==='blank'?'blank':'')}${dimensionOptions.map(d=>option(dimensionKey(d),d.width+' × '+d.length,r.dimensionStatus==='value'?dimensionKey(r.dimension):'')).join('')}${option('__manual','手动输入…','')}</select><div class="cell-hint ${r.dimensionStatus==='pending'?'warning':''}">${r.dimensionStatus==='pending'?'多个尺寸或未确认':r.dimensionStatus==='blank'?'已确认留空':number(r.area,3)+' ㎡'}</div></td><td class="num"><span class="money-result">${number(r.weight,3)}</span></td><td class="num"><span class="money-result">${number(r.cost)}</span></td><td><span class="status-text ${r.status}">${r.status==='pending'?'待复核':r.status==='blank'?'已留空':'已确认'}</span></td></tr>`;
  }
  function library(){return header('可复用规则','各材质、厚度对应的重量系数与成本。','')+`<section class="wide-content"><div class="library-heading"><h2>材质与厚度成本</h2><span>示例规则</span></div><div class="table-scroller" tabindex="0" aria-label="材质与厚度成本规则，可横向滚动"><table class="material-rule-table"><thead><tr><th>材质</th><th class="num">厚度 / mm</th><th class="num">重量系数 / kg/㎡</th><th class="num">成本 / 元/㎡</th></tr></thead><tbody>${state.materials.flatMap(m=>m.rules.map(r=>`<tr><td>${esc(m.name)}</td><td class="num">${r.thickness}</td><td class="num">${number(r.coefficient,2)}</td><td class="num">${number(r.costPerSqm,2)}</td></tr>`)).join('')}</tbody></table></div></section>`;}
  function render(focusName){if(groupUndo&&(groupUndo.after!==JSON.stringify(state.rows))){groupUndo=null;document.querySelector('#thickness-toast').classList.remove('visible');}const visibleIds=new Set(shownRows().map(r=>r.id));selected=new Set([...selected].filter(id=>visibleIds.has(id)));app.innerHTML=`<div class="app-shell">${nav()}<div class="workspace thickness-page"><header class="topbar"><div class="crumbs"><span>地垫旗舰店</span>${icon('chevron-right')}<strong>${view==='product'?'商品转表':'可复用规则'}</strong></div><div class="topbar-right"><span class="prototype-label">综合复核原型</span><span class="cache-label">示例数据</span></div></header><main id="main-content">${view==='product'?product():library()}</main><footer class="prototype-footer"><span>交互方案待复核 · 仅使用示例数据，刷新后重置</span><a href="review-20260918.html">返回完整工作台原型</a></footer></div></div>`;window.lucide?.createIcons();if(view==='product'){const allBox=document.querySelector('[name=select-all]');allBox.indeterminate=selected.size>0&&selected.size<visibleIds.size;M.productGroups(state).forEach((g,i)=>{const box=document.querySelector(`[data-select-group="${i}"]`),visible=g.rows.filter(r=>visibleIds.has(r.id));if(box)box.indeterminate=visible.some(r=>selected.has(r.id))&&!visible.every(r=>selected.has(r.id));});}if(focusName)document.getElementsByName(focusName)[0]?.focus();}
  function close(){dialog.close();modal=null;returnFocus?.focus();}
  function open(type,data={}){returnFocus=document.activeElement;modal={type,...data};paintDialog();dialog.showModal();dialog.querySelector('input:not([type=checkbox]),select,button')?.focus();}
  function frame(title,body,foot){dialog.innerHTML=`<form id="dialog-form"><header class="th-dialog-head"><h2 id="dialog-title">${title}</h2><button type="button" class="icon-btn" data-action="close" aria-label="关闭弹窗">${icon('x')}</button></header><div class="th-dialog-body">${body}<div class="form-error" role="alert" id="form-error"></div></div><footer class="th-dialog-foot">${foot}</footer></form>`;window.lucide?.createIcons();}
  const saveFoot=label=>btn('close','取消')+`<button type="submit" class="btn primary">${label}</button>`;
  function paintDialog(){dialog.classList.toggle('wide',['preview','batch'].includes(modal.type));
    if(modal.type==='batch'){
      const d=modal.batch||{material:'keep',thickness:'keep',dimension:'keep',overwrite:false};modal.batch=d;
      const selectedRows=rows().filter(r=>modal.ids.includes(r.id)),groups=M.productGroups(state).filter(g=>g.rows.some(r=>modal.ids.includes(r.id)));
      frame(modal.title||'批量处理所选规格',`<p class="batch-scope">${esc(modal.scope||('已勾选 '+modal.ids.length+' 个 SKU · '+groups.length+' 个商品'))}</p><div class="batch-field-grid"><label class="field">材质<select name="batch-material">${option('keep','保持原值',d.material)}${option('blank','保留为空',d.material)}${state.materials.map(m=>option(m.id,m.name,d.material)).join('')}</select></label><label class="field">厚度<select name="batch-thickness">${option('keep','保持原值',d.thickness)}${state.materials.filter(m=>!['silica','linen'].includes(d.material)||m.id===d.material).map(m=>`<optgroup label="${m.name}">${m.rules.map(r=>option(m.id+'|'+r.id,m.name+' · '+r.thickness+' mm',d.thickness)).join('')}</optgroup>`).join('')}</select></label><label class="field">尺寸 / cm<select name="batch-dimension">${option('keep','保持原值',d.dimension)}${option('blank','保留为空',d.dimension)}${dimensions.map(x=>option(dimensionKey(x),x.width+' × '+x.length,d.dimension)).join('')}${option('manual','手动输入…',d.dimension)}</select></label></div><div class="default-fields" ${d.dimension==='manual'?'':'hidden'}><label class="field">宽 / cm<input name="batch-width" type="number" min="0.01" max="10000" step="any" value="${esc(d.width||'')}" ${d.dimension==='manual'?'required':''}></label><label class="field">长 / cm<input name="batch-length" type="number" min="0.01" max="10000" step="any" value="${esc(d.length||'')}" ${d.dimension==='manual'?'required':''}></label></div><label class="check-option"><input type="checkbox" name="overwrite" ${d.overwrite?'checked':''}>同时覆盖已确认值（含人工选择与留空）</label><div class="form-help">默认只补待确认字段。“保持原值”始终不修改；厚度只应用于对应材质，同商品不同尺寸保持独立。</div><div id="batch-impact" class="batch-impact" aria-live="polite"></div>`,saveFoot('确认应用'));updateBatchImpact();return;
    }
    if(modal.type==='dimension'){const r=state.rows.find(x=>x.id===modal.rowId);frame('手动确认尺寸',`<p>${esc(r.name)} · ${esc(r.sku)}</p><div class="default-fields"><label class="field">宽 / cm<input type="number" name="width" min="0.01" max="10000" step="any" required value="${r.dimension?.width||''}"></label><label class="field">长 / cm<input type="number" name="length" min="0.01" max="10000" step="any" required value="${r.dimension?.length||''}"></label></div>`,saveFoot('确认尺寸'));return;}
    if(modal.type==='preview'){frame('导出结果预览',`<p>厚度决定每平方米重量和成本。确认留空的单元格保留为空。</p><div class="table-scroller"><table class="preview-table"><thead><tr><th>SKU</th><th>材质</th><th>厚度 / mm</th><th>重量 / kg</th><th>成本 / 元</th></tr></thead><tbody>${rows().map(r=>`<tr><td>${esc(r.sku)}</td><td>${esc(state.materials.find(m=>m.id===r.materialId)?.name||'—')}</td><td>${r.rule?.thickness??'—'}</td><td>${number(r.weight,3)}</td><td>${number(r.cost)}</td></tr>`).join('')}</tbody></table></div><div class="form-help">这是交互原型的结果预览，供确认厚度选择和计算方式。</div>`,btn('close','返回复核')+btn('download','下载预览 CSV','download','primary'));return;}
  }
  function captureBatch(){const f=new FormData(dialog.querySelector('form'));modal.batch={material:f.get('batch-material'),thickness:f.get('batch-thickness'),dimension:f.get('batch-dimension'),width:f.get('batch-width'),length:f.get('batch-length'),overwrite:f.has('overwrite')};}
  function batchPatch(){const d=modal.batch,patch={};if(d.material!=='keep')patch.material=d.material==='blank'?'':d.material;if(d.thickness!=='keep'){const [materialId,ruleId]=d.thickness.split('|');patch.thickness={materialId,ruleId};}if(d.dimension!=='keep'){const [width,length]=d.dimension.split('x').map(Number);patch.dimension=d.dimension==='blank'?null:d.dimension==='manual'?{width:Number(d.width),length:Number(d.length)}:{width,length};}return patch;}
  function updateBatchImpact(){try{const out=M.previewReview(state,modal.ids,batchPatch(),modal.batch.overwrite);dialog.querySelector('#batch-impact').textContent=`将更新 ${out.changed} 个 SKU：材质 ${out.counts.material} 项 / 厚度 ${out.counts.thickness} 项 / 尺寸 ${out.counts.dimension} 项。${out.protected?' 已确认字段受保护。':''}${out.incompatible?' '+out.incompatible+' 行材质不匹配或已留空，跳过厚度。':''}`;}catch(error){dialog.querySelector('#batch-impact').textContent=error.message;}}
  document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
    try{
      if(a==='close')return close();
      if(a==='menu'){menu=!menu;return render();}
      if(a==='library'||a==='product'){view=a;menu=false;render();document.querySelector('h1')?.scrollIntoView({block:'start'});return;}
      if(a==='filter'){filter=el.dataset.value;return render(el.name);}
      if(a==='more-filters'){moreFilters=!moreFilters;return render(el.name);}
      if(a==='filter-unwritten'){unwrittenOnly=!unwrittenOnly;return render(el.name);}
      if(a==='batch')return open('batch',{ids:[...selected]});
      if(a==='undo-group'){if(!groupUndo)return;const {before,focusName}=groupUndo;state.rows=before;groupUndo=null;render(focusName);return toast('已撤销本次同链接修改');}
      if(a==='preview-export'){if(rows().some(r=>r.status==='pending'))return;return open('preview');}
      if(a==='download'){
        const csvValue=x=>'"'+String(x??'').replace(/"/g,'""')+'"';
        const values=[['SKU','材质','厚度（mm）','重量（kg）','成本（元）'],...rows().map(r=>[r.sku,state.materials.find(m=>m.id===r.materialId)?.name||'',r.rule?.thickness??'',r.weight==null?'':number(r.weight,3),r.cost==null?'':number(r.cost)])];
        const url=URL.createObjectURL(new Blob(['\ufeff'+values.map(row=>row.map(csvValue).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));
        const link=document.createElement('a');link.href=url;link.download='厚度复核-示例预览.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return toast('已下载示例结果');
      }
    }catch(error){toast(error.message);}
  });
  document.addEventListener('change',event=>{const el=event.target;
    try{
      if(modal?.type==='batch'&&(el.name.startsWith('batch-')||el.name==='overwrite')){captureBatch();if(el.name==='batch-material'&&modal.batch.thickness!=='keep'&&!modal.batch.thickness.startsWith(modal.batch.material+'|'))modal.batch.thickness='keep';if(['batch-material','batch-thickness','batch-dimension'].includes(el.name))return paintDialog();return updateBatchImpact();}
      if(el.dataset.groupMaterial!==undefined)return applyGroup(Number(el.dataset.groupMaterial),'material',el.value,el.name);
      if(el.dataset.groupThickness!==undefined)return applyGroup(Number(el.dataset.groupThickness),'thickness',el.value,el.name);
      if(el.dataset.selectGroup){const g=M.productGroups(state)[Number(el.dataset.selectGroup)];const visibleIds=new Set(shownRows().map(r=>r.id));for(const r of g.rows.filter(r=>visibleIds.has(r.id)))el.checked?selected.add(r.id):selected.delete(r.id);return render(el.name);}
      if(el.name==='filter-unwritten'){unwrittenOnly=!unwrittenOnly;return render(el.name);}
      if(el.name==='select-all'){for(const r of shownRows())el.checked?selected.add(r.id):selected.delete(r.id);return render(el.name);}
      if(el.dataset.selectRow){el.checked?selected.add(el.dataset.selectRow):selected.delete(el.dataset.selectRow);return render(el.name);}
      if(el.dataset.rule){if(!el.value)return render(el.name);M.selectRule(state,el.dataset.rule,el.value);render(el.name);return toast('厚度已确认，重量与成本已重算');}
      if(el.dataset.material){if(el.value==='__pending')return;M.setMaterial(state,el.dataset.material,el.value);render(el.name);return;}
      if(el.dataset.dimension){if(el.value==='__pending')return;if(el.value==='__manual')return open('dimension',{rowId:el.dataset.dimension});const [width,length]=el.value.split('x').map(Number);M.setDimension(state,el.dataset.dimension,el.value==='blank'?null:{width,length});return render(el.name);}
    }catch(error){toast(error.message);render();}
  });
  dialog.addEventListener('input',event=>{if(modal?.type==='batch'&&['batch-width','batch-length'].includes(event.target.name)){captureBatch();updateBatchImpact();}});
  dialog.addEventListener('submit',event=>{event.preventDefault();try{const data=new FormData(event.target),kind=modal.type;
    if(kind==='batch'){captureBatch();const result=M.applyReview(state,modal.ids,batchPatch(),modal.batch.overwrite);close();selected.clear();render();toast('已更新 '+result.changed+' 个 SKU，材质 '+result.counts.material+' / 厚度 '+result.counts.thickness+' / 尺寸 '+result.counts.dimension);}
    else if(kind==='dimension'){M.setDimension(state,modal.rowId,{width:Number(data.get('width')),length:Number(data.get('length'))});close();render();toast('尺寸已确认，重量成本已重算');}
  }catch(error){document.querySelector('#form-error').textContent=error.message;}});
  dialog.addEventListener('cancel',event=>{event.preventDefault();close();});
  dialog.addEventListener('close',()=>{returnFocus?.isConnected&&returnFocus.focus();});
  render();
})();
